let state;
const form = document.querySelector("form");
const error = document.querySelector("[data-hook=form-error]");
const list = document.getElementById("answers");
const render = () => list.replaceChildren(...state.data.answers.map((answer) => {
  const item = document.createElement("li");
  item.dataset.hook = "answer";
  item.textContent = [answer.name, answer.people + (answer.people === 1 ? " person" : " people"), answer.allergies].filter(Boolean).join(", ");
  return item;
}));
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
load();
// A form never submits in Tessera, so the button's click sends it.
document.querySelector("[data-hook=form-submit]").addEventListener("click", () => {
  const missing = [...form.elements].filter((field) => field.required && !field.value.trim());
  if (missing.length > 0) {
    error.textContent = "Please fill in: " + missing.map((field) => field.labels[0].textContent.trim()).join(", ") + ".";
    return;
  }
  error.textContent = "";
  const record = {
    name: form.elements.name.value.trim(),
    people: Number(form.elements.people.value),
    allergies: form.elements.allergies.value.trim(),
  };
  tessera.call("data.patch", { operations: [{ op: "add", collection: "answers", record }] }).then(() => {
    form.reset();
    return load();
  });
});
